(function(){
  var D='零壹贰叁肆伍陆柒捌玖', S=['','拾','佰','仟'], B=['','万','亿','兆'];
  function intToCn(num){ num=String(num).replace(/^0+/,''); if(num==='') return '零';
    var groups=[]; for(var i=num.length;i>0;i-=4) groups.unshift(num.slice(Math.max(0,i-4),i));
    var out='';
    for(var g=0;g<groups.length;g++){ var grp=groups[g], sec='', zero=false;
      for(var p=0;p<grp.length;p++){ var d=+grp[p], pos=grp.length-1-p;
        if(d===0){ zero=true; } else { if(zero&&sec!=='') sec+='零'; sec+=D[d]+S[pos]; zero=false; } }
      if(sec!=='') out+=sec+B[groups.length-1-g];
      else if(out!=='' && g<groups.length-1 && !/零$/.test(out)) out+='零';
    }
    return out.replace(/零+/g,'零').replace(/零$/,''); }
  function toUpper(amount){ amount=String(amount).trim();
    if(amount==='') return {error:'空输入'};
    if(!/^-?\d+(\.\d{1,2})?$/.test(amount)) return {error:'仅支持数字（最多两位小数）'};
    var neg=amount[0]==='-'; if(neg) amount=amount.slice(1);
    var parts=amount.split('.'), intPart=parts[0], dec=parts[1]||'';
    var intCn=intToCn(intPart), res='';
    if(dec===''){ res=intCn+'元整'; }
    else { var jiao=dec[0]||'0', fen=dec[1]||'0'; res=intCn+'元';
      if(jiao!=='0') res+=D[+jiao]+'角';
      if(fen!=='0') res+=D[+fen]+'分';
      if(jiao==='0'&&fen==='0') res+='整'; else if(fen==='0') res+='整'; }
    return {value:(neg?'负':'')+res}; }
  var API={toUpper:toUpper};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__CnyForge__=API;
})();
